WITH RECURSIVE climb AS (SELECT trace_id, span_id AS seed, parent_span_id AS cur, 0 AS depth FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND (multiIf(dynamicType(attrs.`b`) != 'None', (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`b`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`b`), arrayExists(x -> x = 2, events.attrs.`b`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`b`), arrayExists(x -> x = 2, links.attrs.`b`.:Int64), multiIf(dynamicType(scope_attrs.`b`) != 'None', (coalesce(scope_attrs.`b`.:Int64 = 2, false) OR coalesce(scope_attrs.`b`.:Float64 = 2, false)), false)))))) UNION ALL SELECT c.trace_id, c.seed, x.parent_span_id, c.depth + 1 FROM climb AS c INNER JOIN (SELECT trace_id, span_id, parent_span_id FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666) AS x ON x.trace_id = c.trace_id AND x.span_id = c.cur WHERE c.depth < 64), pairs AS (SELECT DISTINCT c.trace_id AS trace_id, c.seed AS seed, c.cur AS other FROM climb AS c INNER JOIN (SELECT trace_id, span_id FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND (multiIf(dynamicType(attrs.`a`) != 'None', (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`a`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`a`.:Int64 = 1, false) OR coalesce(attrs.`a`.:Float64 = 1, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`a`), arrayExists(x -> x = 1, events.attrs.`a`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`a`), arrayExists(x -> x = 1, links.attrs.`a`.:Int64), multiIf(dynamicType(scope_attrs.`a`) != 'None', (coalesce(scope_attrs.`a`.:Int64 = 1, false) OR coalesce(scope_attrs.`a`.:Float64 = 1, false)), false))))))) AS r ON r.trace_id = c.trace_id AND r.span_id = c.cur) SELECT span FROM (SELECT lower(hex(span_id)) AS span FROM tqd_cat.spans WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND (multiIf(dynamicType(attrs.`b`) != 'None', (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`b`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`b`.:Int64 = 2, false) OR coalesce(attrs.`b`.:Float64 = 2, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`b`), arrayExists(x -> x = 2, events.attrs.`b`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`b`), arrayExists(x -> x = 2, links.attrs.`b`.:Int64), multiIf(dynamicType(scope_attrs.`b`) != 'None', (coalesce(scope_attrs.`b`.:Int64 = 2, false) OR coalesce(scope_attrs.`b`.:Float64 = 2, false)), false)))))) AND (trace_id, span_id) IN (SELECT trace_id, seed FROM pairs)) ORDER BY span FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
